function stripCdata(s) {
  return s.replace(/^<!\[CDATA\[([\s\S]*?)\]\]>$/, '$1').trim();
}

function stripHtml(s) {
  return s.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

const CITY_MAP = {
  'Markham': 'Markham',
  'Unionville': 'Markham',
  'Thornhill': 'Vaughan',
  'Vaughan': 'Vaughan',
  'Richmond Hill': 'Richmond Hill',
};

const itemBlocks = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;
while ((match = itemRegex.exec(xml)) !== null) {
  itemBlocks.push(match[1]);
}

const get = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))<\\/${tag}>`));
  return m ? (m[1] ?? m[2] ?? '').trim() : '';
};

const getBC = (block, field) => {
  const m = block.match(new RegExp(`<bc:${field}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))<\/bc:${field}>`));
  return m ? (m[1] ?? m[2] ?? '').trim() : '';
};

const getAudience = (block) => {
  const matches = [...block.matchAll(/<category[^>]*domain="Audience"[^>]*>(?:<!\[CDATA\[([\s\S]*?)\]\]>|([\s\S]*?))<\/category>/g)];
  return matches.map(m => (m[1] ?? m[2] ?? '').trim()).filter(Boolean).join(', ');
};

// Extract a sub-field from within bc:location XML
const getFromLocation = (locationXml, field) => {
  const m = locationXml.match(new RegExp(`<bc:${field}[^>]*>([^<]*)<\/bc:${field}>`));
  return m ? m[1].trim() : '';
};

const results = [];

for (const block of itemBlocks) {
  const title = decodeEntities(get(block, 'title'));
  const link = get(block, 'link');
  const startRaw = getBC(block, 'start_date');
  const endRaw = getBC(block, 'end_date');
  const locationXml = getBC(block, 'location');
  const descriptionRaw = stripCdata(get(block, 'description'));
  const description = stripHtml(decodeEntities(descriptionRaw));
  const audience = getAudience(block);

  if (!title || !startRaw) continue;

  const isoDate = new Date(startRaw).toISOString();
  const endDate = endRaw ? endRaw.split('T')[0] : '';

  const locationName = getFromLocation(locationXml, 'name');
  const bcCity = getFromLocation(locationXml, 'city');
  const city = CITY_MAP[bcCity] || null;

  // Skip events from cities outside our coverage area
  if (!city) continue;

  // Skip online/virtual events (no location)
  if (!locationName) continue;

  const DescriptionRaw = audience
    ? `Audience: ${audience}\n\n${description}`
    : description;

  results.push({
    json: {
      title,
      event_name: title,
      link,
      url: link,
      isoDate,
      start_date: isoDate,
      endDate,
      locationName,
      city,
      sourceCanonical: 'BiblioCommons Markham',
      DescriptionRaw,
      _valid: !!(title && isoDate && link),
    }
  });
}

return results;

const response = $input.first().json;
const events = response.data || [];

