  if (!s) return '';
  return s
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

const CITY_MAP = {
  'Vaughan': 'Vaughan',
  'Woodbridge': 'Vaughan',
  'Thornhill': 'Vaughan',
  'Maple': 'Vaughan',
  'Concord': 'Vaughan',
  'Richmond Hill': 'Richmond Hill',
  'Markham': 'Markham',
  'Unionville': 'Markham',
};

const results = [];

for (const ev of events) {
  const venue = ev.venue || {};
  const venueCity = (venue.city || '').trim();
  const city = CITY_MAP[venueCity];
  if (!city) continue;

  const title = decodeEntities((ev.eventname || '').toString().trim());
  const eventUrl = (ev.event_url || ev.share_url || '').toString().trim();
  if (!title || !eventUrl) continue;

  const startTs = ev.start_time;
  if (!startTs) continue;
  const isoDate = new Date(startTs * 1000).toISOString();

  const endTs = ev.end_time;
  const endDate = endTs ? new Date(endTs * 1000).toISOString().slice(0, 10) : '';

  const fullAddress = decodeEntities((venue.full_address || '').toString().trim());
  const locationName = fullAddress.split(',')[0].trim();

  const categories = Array.isArray(ev.categories)
    ? ev.categories.filter(Boolean).join(', ')
    : (ev.categories || '').toString();

  const organizer = decodeEntities(((ev.organizer && ev.organizer.name) || ev.organizer || '').toString().trim());
  const allEventsScore = ev.score != null ? ev.score : null;

  const descParts = [];
  if (categories) descParts.push(`AllEvents Categories: ${categories}`);
  if (organizer) descParts.push(`AllEvents Organizer: ${organizer}`);
  if (allEventsScore != null) descParts.push(`AllEvents Score: ${allEventsScore}`);
  const DescriptionRaw = descParts.join('\n');

  results.push({
    json: {
      title,
      event_name: title,
      link: eventUrl,
      url: eventUrl,
      isoDate,
      start_date: isoDate,
      endDate,
      locationName,
      city,
      sourceCanonical: 'AllEvents',
      DescriptionRaw,
      _valid: !!(title && isoDate && eventUrl),
    }
  });
}

return results;

