    ? ev.categories.filter(Boolean).join(', ')
    : (ev.categories || '').toString();

  const organizer = decodeEntities(((ev.organizer && ev.organizer.name) || ev.organizer || '').toString().trim());
  const allEventsScore = ev.score != null ? ev.score : null;

  const descParts = [];
  if (categories) descParts.push(`AllEvents Categories: ${categories}`);
  if (organizer) descParts.push(`AllEvents Organizer: ${organizer}`);
  if (allEventsScore != null) descParts.push(`AllEvents Score: ${allEventsScore}`);
  const DescriptionRaw = descParts.join('\n');

  results.push({
    json: {
      title,
      event_name: title,
      link: eventUrl,
      url: eventUrl,
      isoDate,
      start_date: isoDate,
      endDate,
      locationName,
      city,
      sourceCanonical: 'AllEvents',
      DescriptionRaw,
      _valid: !!(title && isoDate && eventUrl),
    }
  });
}

return results;

// Group DateWindow output into Airtable batch-upsert bodies (10 records/request).
// Mirrors the old 'Upsert Candidates' field mapping exactly; matches on UniqueEventID.
// Empty values are omitted (avoids 400 on empty date fields; never blanks an existing value).
const FIELD_MAP = {
  'Event Title': 'event_name',
  'City': 'city',
  'URL': 'url',
  'Start Date': 'start_date',
  'End Date': 'endDate',
  'DescriptionRaw': 'DescriptionRaw',
  'UniqueEventID': 'uniqueEventID',
  'LocationName': 'locationName',
  'Source': 'sourceCanonical',
};
const now = new Date().toISOString();
function buildFields(j) {
  const f = {};
  for (const [col, key] of Object.entries(FIELD_MAP)) {
    const v = j[key];
    if (v !== undefined && v !== null && v !== '') f[col] = v;
  }
  f['Last Auto Update'] = now;
  return f;
}
// Dedupe by UniqueEventID across the whole run (last occurrence wins, matching the
// old per-record last-write-wins). Airtable rejects a batch that updates the same
// record twice in one request, and re-upserting the same event in a run is pointless.
const seen = new Map();   // id -> last json (the survivor)
const groups = new Map(); // id -> [all jsons with this id]
for (const i of items) {
  const id = i.json.uniqueEventID;
  if (!id) continue;
  if (!groups.has(id)) groups.set(id, []);
  groups.get(id).push(i.json);
  seen.set(id, i.json);
}
// --- Collision diagnostics: which keys collapsed, and is it benign? ---
// Same UniqueEventID + SAME url  = genuinely the same event (benign collapse).
// Same UniqueEventID + DIFFERENT urls = two different events merged on a coarse
// title|date key (potential wrongful loss — inspect these).
const collisions = [...groups.entries()].filter(([, arr]) => arr.length > 1);
const collapsed = items.length - seen.size;
console.log(`[dedup] ${items.length} items in -> ${seen.size} unique (${collapsed} collapsed across ${collisions.length} keys)`);
let urlDiffers = 0;
for (const [id, arr] of collisions) {
  const urls = new Set(arr.map((r) => r.url));
  const venues = new Set(arr.map((r) => (r.locationName || '').trim()).filter(Boolean));
  const bad = urls.size > 1;
  if (bad) urlDiffers++;
  console.log(`  x${arr.length} urls=${urls.size} venues=${venues.size} "${id}"${bad ? ' [URLS DIFFER - INSPECT]' : ''}`);
}
console.log(`[dedup] ${urlDiffers} collision key(s) had DIFFERING urls (potential wrongful merge; 0 = all collapses benign)`);

const records = [...seen.values()].map((j) => ({ fields: buildFields(j) }));
const out = [];
for (let k = 0; k < records.length; k += 10) {
  out.push({
    json: {
      records: records.slice(k, k + 10),
      performUpsert: { fieldsToMergeOn: ['UniqueEventID'] },
      typecast: true,
    }
  });
}
return out;
